// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzz parameter: an address that will act as the player
    function testFuzz_property(address player) public {
        // keep player as a non-zero address and not the test contract to be meaningful
        vm.assume(player != address(0));
        vm.assume(player != address(this));

        // fund the player so they can send 1 ether
        vm.deal(player, 2 ether);

        // prepare a guess hash (any bytes32). Fuzzer could vary player only; that's sufficient
        bytes32 guess = keccak256(abi.encodePacked(player, block.number));

        // record current block for later comparison
        uint256 beforeBlock = block.number;

        // call lockInGuess as the player sending exactly 1 ether
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(guess);

        // Read the stored block from the contract's public mapping getter
        // The struct is named `guess` in the contract; its mapping is `guesses` so getter is guesses(address)
        (uint256 storedBlock, bytes32 storedGuess) = c.guesses(player);

        // GENERAL RULE (single assertion): for the correct contract, the stored block must be strictly greater
        // than the block when lockInGuess was executed (i.e., it recorded block.number + 1). The mutant that
        // records current block will make storedBlock == beforeBlock, violating this for some player (fuzzer finds one).
        assertTrue(storedBlock > beforeBlock);

        // (Note: also ensures guess was recorded, but the single required assertion is above)
        // silence unused variable warning in case of compilation nuances
        storedGuess; 
    }
}

