pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzz the caller address and a nonzero guess value
    function testFuzz_property(address player, bytes32 guessHash) public {
        // keep player as a regular EOA (non-zero) and ensure we have distinct addresses
        vm.assume(player != address(0));

        // fund the player so they can send 1 ether
        vm.deal(player, 2 ether);

        // record current block number before the call
        uint256 before = block.number;

        // perform the call as player sending exactly 1 ether
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(guessHash);

        // read the recorded block via the auto-generated getter for the public mapping
        // mapping(address => guess) guesses; where guess has member 'block' named 'block'
        // The compiler generates a getter: guesses(address) returns (uint256, bytes32)
        (uint256 storedBlock, bytes32 storedGuess) = c.guesses(player);

        // The invariant: the stored block must be strictly greater than the block at call time
        // (i.e., contract records next block). This holds for the reference; the mutant that
        // records the current block will sometimes have storedBlock == before, violating this.
        assertTrue(storedBlock > before);
    }
}

