pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: actor address and a nonzero seed for guess bytes32; blockNumberDelta lets fuzzer advance blocks
    function testFuzz_property(address actor, uint256 seed, uint256 blockNumberDelta) public {
        // keep actor non-zero and seed wide; allow blockNumberDelta up to a reasonable range
        vm.assume(actor != address(0));
        // bound blockNumberDelta so we can warp forward but keep it wide enough to find differences
        blockNumberDelta = bound(blockNumberDelta, 0, 100);

        // fund the actor so they can send 1 ether
        vm.deal(actor, 5 ether);

        // craft a guess value from seed (fuzzer supplies seed)
        bytes32 guess = bytes32(seed);

        // Optionally advance block a bit to vary block.number
        vm.warp(block.timestamp + (blockNumberDelta * 1));
        // ensure we're not at block 0; advance block number by mining some blocks
        for (uint i = 0; i < (blockNumberDelta % 5); ++i) { vm.roll(block.number + 1); }

        // actor calls lockInGuess with exactly 1 ether
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // After the call completes, in the correct contract the stored block for actor equals block.number + 1
        // Read the stored struct via the auto getter: guesses(address) returns (uint256, bytes32)
        (uint256 recordedBlock, bytes32 recordedGuess) = c.guesses(actor);

        // single assertion: recordedBlock equals block.number + 1 OR the recorded guess is zero (meaning no record)
        // However by construction we just called lockInGuess successfully with 1 ether when there was no prior guess,
        // so the invariant is: recordedBlock == block.number + 1.
        // We assert that equality; the mutant storing block.number+2 will fail this for some fuzzed inputs.
        assertTrue(recordedBlock == block.number + 1);
    }
}

