pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzz the caller address and a random bytes32 guess; the fuzzer will find cases
    // where the mutant (which sets stored block to 1) deviates from the reference
    function testFuzz_property(address caller, bytes32 guessHash) public {
        // keep caller non-zero and not the contract itself
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // fund the caller so they can send 1 ether
        vm.deal(caller, 2 ether);

        // perform the call as the caller, sending exactly 1 ether
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(guessHash);

        // The reference contract always sets guesses[caller].block == block.number + 1
        // after lockInGuess; the buggy mutant sets it to 1. We assert the universal
        // property that the stored block equals current block + 1 at the time of the call.
        // We read the stored value via the autogenerated public getter for `guesses`.
        (, uint256 storedBlock) = _readGuess(caller);

        // exactly one assertion: the stored block equals the block in which the guess
        // will be settled (i.e. block.number at call time + 1). Because we executed
        // lockInGuess in the same transaction, the recorded value in the correct
        // contract is current block.number + 1; the mutant will often be 1 and thus
        // violate this assertion for many inputs (fuzzer will find such inputs).
        assertTrue(storedBlock == block.number + 1);
    }

    // helper to call the autogenerated getter for the public mapping `guesses`
    function _readGuess(address who) internal returns (bytes32 g, uint256 b) {
        // The contract C has: mapping(address => guess) guesses;
        // The compiler generates: function guesses(address) external view returns (bytes32 guess, uint256 block);
        // But since the getter is view, we can call it. We use a low-level call via abi.encodeWithSignature
        // to avoid needing the exact return types in the import.
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSignature("guesses(address)", who));
        require(ok);
        (bytes32 guessVal, uint256 blockVal) = abi.decode(ret, (bytes32, uint256));
        return (guessVal, blockVal);
    }
}

