pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzz the caller address and an arbitrary bytes32 guess
    function testFuzz_property(address caller, bytes32 guessHash) public {
        // keep caller non-zero and not the contract itself
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // fund the caller so they can send 1 ether
        vm.deal(caller, 2 ether);

        // perform the lockInGuess from the fuzzed caller, paying exactly 1 ether
        vm.prank(caller);
        bool ok;
        try c.lockInGuess{value: 1 ether}(guessHash) {
            ok = true;
        } catch {
            // If call reverted, then reference contract refuses the input; in that case
            // we restrict to admissible inputs by assuming the call succeeds — but we
            // cannot call vm.assume here after observing revert, so instead we simply
            // return early for this failing case. This keeps domain wide: only cases
            // where lockInGuess succeeds are considered.
            return;
        }

        // The universal property: for ANY admissible input where lockInGuess succeeded,
        // the stored block for the caller equals block.number + 1 (as recorded at lock time).
        // Read the stored value via the auto-generated public getter for the mapping.
        // guesses is a public mapping of address->guess struct; solidity generates
        // a getter guesses(address) returning (uint,bytes32) in that order.
        (uint storedBlock, bytes32 storedGuess) = c.guesses(caller);

        // exactly one assertion: the reference contract ensures storedBlock == block.number + 1
        // Note: when running on the mutant, for many inputs this will fail because mutant writes 1.
        assertTrue(storedBlock == block.number + 1);

        // also sanity-check the stored guess matches what we set (non-essential to property)
        assertTrue(storedGuess == guessHash);
    }
}

