pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: actor (address) and a guess value
    function testFuzz_property(address actor, bytes32 guessHash) public {
        // keep actor as a non-zero address and not the test contract itself
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // ensure actor has funds to pay 1 ether
        vm.deal(actor, 2 ether);

        // actor calls lockInGuess paying exactly 1 ether
        vm.prank(actor);
        // call and ensure it doesn't revert (we capture revert as false)
        bool ok;
        try c.lockInGuess{value: 1 ether}(guessHash) {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call succeeded, then in the correct contract the stored block for actor
        // must be nonzero and (except the special case block.number+1 == 1) must not equal 1.
        // We assert a single universal property reading c: if the call succeeded and block.number+1 != 1,
        // then the stored guesses[actor].block != 1.
        // This distinguishes the mutant that always writes 1.

        if (ok && (block.number + 1 != 1)) {
            // read the stored block via the auto-getter for the public mapping's struct field
            // The struct is named `guess` and mapping `guesses` has public getter that returns (uint, bytes32)
            (uint storedBlock, ) = c.guesses(actor);
            assertTrue(storedBlock != 1);
        } else {
            // If the call reverted or block.number+1 == 1, we still must assert something about c.
            // In that case, assertTrue(ok || block.number + 1 == 1) keeps the single-assert rule
            // and is true for the reference in all admissible inputs.
            assertTrue(ok || block.number + 1 == 1);
        }
    }
}

