// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // Fuzz the caller address and the guess value (bytes32). We must ensure the caller is not the zero address
    // and give them funds to call with 1 ether. The general rule we assert: after calling lockInGuess with 1 ether
    // as a fresh caller, the stored guess for that caller equals the bytes32 provided.
    function testFuzz_property(address caller, bytes32 guess) public {
        vm.assume(caller != address(0));
        // fund the caller so it can send 1 ether
        vm.deal(caller, 2 ether);

        // Ensure caller has no previous guess stored: we can't directly check internal mapping, but we can
        // perform the call and then use the publicly observable behavior: successful completion and no revert.
        // Make the call as the caller
        vm.prank(caller);
        // call must send exactly 1 ether
        bool ok;
        try c.lockInGuess{value: 1 ether}(guess) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract always accepts this fresh 1 ether call (ok == true) and stores the provided guess.
        // We observe the property by attempting to call settle immediately after: if the guess was stored, the contract
        // recorded block > 0 and stored guess == provided hash; however settle will only pay out after the target block
        // passes, so instead we assert that the call succeeded and that the stored guess equals the provided hash by
        // calling lockInGuess again which should revert because guesses[msg.sender].block != 0 in the reference.
        // We use try/catch to observe whether a second lockInGuess reverts (ok2==false) — in the reference it MUST revert,
        // because the first call set block != 0 and guess to the provided value; in the mutant that assigned block before
        // guess, there exist inputs/timings where the mapping ends up in a state that allows the second call to succeed.

        vm.prank(caller);
        bool ok2;
        try c.lockInGuess{value: 1 ether}(bytes32(0xdead)) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // General property to assert: for any admissible caller and guess, after a successful first lockInGuess call,
        // a second immediate lockInGuess with correct value MUST revert (ok2 == false). The buggy mutant can allow ok2 == true
        // for some inputs/timings and thus will fail this universal property.
        assertTrue(ok == true && ok2 == false);
    }
}

