pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzz params: actor address (who will lock a guess) and a bytes32 guess value
    function testFuzz_property(address actor, bytes32 h) public {
        // keep actor non-zero and distinct from this contract to be a valid caller
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // fund the actor so they can send 1 ether
        vm.deal(actor, 1 ether);

        // actor locks in a guess in the current block
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);

        // Now we call settle in the SAME block as lockInGuess (no warp/roll between)
        // The correct contract requires block.number > lockedBlock, so calling in the same block
        // should NOT allow settle to proceed to clear the stored entry; specifically, after
        // the settle call in the same block the stored guesses[actor].block must still be non-zero.
        // The mutant that changed the check to >= permits clearing in the same block and thus
        // will make this assertion fail for some inputs (the fuzzer will find one).

        // Call settle as the same actor in the same block
        vm.prank(actor);
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // Read address(c).balance to infer if a payout could have occurred, but the core check
        // we assert is that the stored block for actor remains non-zero after calling settle in the same block.
        // We cannot access internal mapping directly; however the contract's behavior can be observed
        // by attempting to lockInGuess again: lockInGuess requires guesses[actor].block == 0.
        // If the stored block remained non-zero (correct contract), a subsequent lockInGuess in the SAME block
        // would revert; but we cannot assert on revert directly per rules except via try/catch. We'll use that.

        // Try locking again: should revert on the reference (since block value still non-zero),
        // while the mutant (which cleared it) would allow it to proceed (and require 1 ether). We prepare actor funds.
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        bool couldLockAgain;
        try c.lockInGuess{value: 1 ether}(h) {
            couldLockAgain = true;
        } catch {
            couldLockAgain = false;
        }

        // The universal property we assert: for all admissible inputs (actor != 0, actor != this)
        // the reference contract ensures that calling settle in the same block does NOT clear the lock,
        // therefore attempting to lock again in the same block MUST fail (couldLockAgain == false).
        // The mutant that permits settle in the same block will sometimes clear it and thus allow lockInGuess,
        // making couldLockAgain == true for some input — causing this assertion to fail on the mutant.
        assertTrue(couldLockAgain == false);
    }
}

