pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // Fuzzed params: an actor (the locker) and a bytes32 guess value.
    // We test the universal property: if an address locks a guess in block B,
    // then attempting to call settle in the same block B must revert on the reference.
    // The mutant that uses >= will allow the same-block settle to proceed for some inputs,
    // so the test will fail on the mutant.
    function testFuzz_property(address locker, bytes32 h) public {
        // keep locker nonzero and avoid the test contract itself to be safe
        vm.assume(locker != address(0));
        vm.assume(locker != address(this));

        // Fund the locker so it can pay 1 ether for lockInGuess
        vm.deal(locker, 2 ether);

        // Have locker call lockInGuess in the current block
        vm.prank(locker);
        c.lockInGuess{value: 1 ether}(h);

        // Immediately (same block) attempt to call settle as locker.
        // On the correct contract this should revert because settle requires block.number > guesses[locker].block,
        // meaning same-block settle is not permitted. The mutant (>=) will allow it.
        bool ok;
        try c.settle{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for all admissible inputs (any locker and h), the correct contract
        // will revert when settle is called in the same block; thus ok must be false.
        // The mutant violates this for some inputs (it may make ok == true), so this assertion
        // distinguishes the mutant from the reference.
        assertTrue(!ok);
    }
}
